      hu: ["Keleti-fjordok", "Történelmi kereskedelmi központ", "Gazdag madárvilág", "Hegyek"],
      ro: ["Fiordurile de Est", "Centru comercial istoric", "Avifaună bogată", "Munți"],
      en: ["Eastfjords", "Historic trading post", "Rich birdlife", "Mountains"],
